<?php
/**
 * Email method.
 *
 * @package PotomacTech\MFA
 */

namespace PotomacTech\MFA\Methods;

use PotomacTech\MFA\Settings\Options;
use PotomacTech\MFA\User\UserState;

defined( 'ABSPATH' ) || exit;

/**
 * Codes generated by the plugin and delivered with wp_mail(). No per-message provider fee.
 */
final class EmailMethod implements MethodInterface {

	private const MAX_ATTEMPTS = 5;

	public function key(): string {
		return 'email';
	}

	public function label(): string {
		return __( 'Email', 'potomac-mfa' );
	}

	public function is_available(): bool {
		return in_array( 'email', (array) Options::get( 'methods.enabled', array() ), true );
	}

	public function is_enrolled( int $user_id ): bool {
		return UserState::has_method( $user_id, 'email' ) && '' !== UserState::email( $user_id );
	}

	public function delivers_code(): bool {
		return true;
	}

	public function send( \WP_User $user ): Result {
		return $this->send_to( $user, UserState::email( $user->ID ), 'login' );
	}

	public function verify( \WP_User $user, string $code ): Result {
		return $this->check( $user->ID, UserState::email( $user->ID ), $code, 'login' );
	}

	/**
	 * Generate and email a code for a purpose (login or enroll).
	 */
	public function send_to( \WP_User $user, string $address, string $purpose ): Result {
		if ( ! is_email( $address ) ) {
			return new Result( Result::ERROR, __( 'No valid email address is on file.', 'potomac-mfa' ) );
		}
		$code    = str_pad( (string) random_int( 0, 999999 ), 6, '0', STR_PAD_LEFT );
		$minutes = (int) Options::get( 'email.ttl_minutes', 10 );
		/**
		 * Filter the code lifetime in seconds.
		 *
		 * @param int    $ttl    Lifetime in seconds.
		 * @param string $method Method key.
		 */
		$ttl = (int) apply_filters( 'pmfa_code_ttl', $minutes * MINUTE_IN_SECONDS, 'email' );

		$tokens  = array(
			'{code}'         => $code,
			'{site_name}'    => wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ),
			'{site_url}'     => home_url( '/' ),
			'{user_login}'   => $user->user_login,
			'{display_name}' => $user->display_name,
			'{minutes}'      => (string) max( 1, intdiv( $ttl, 60 ) ),
		);
		$subject = strtr( (string) Options::get( 'email.subject' ), $tokens );
		$body    = strtr( (string) Options::get( 'email.body' ), $tokens );

		/**
		 * Filter the email message before sending.
		 *
		 * @param array{to:string,subject:string,body:string,headers:array} $message Message.
		 * @param \WP_User $user    Recipient.
		 * @param string   $purpose login | enroll.
		 */
		$message = apply_filters(
			'pmfa_email_message',
			array(
				'to'      => $address,
				'subject' => $subject,
				'body'    => $body,
				'headers' => self::headers(),
			),
			$user,
			$purpose
		);

		$sent = wp_mail( $message['to'], $message['subject'], $message['body'], $message['headers'] );
		if ( ! $sent ) {
			return new Result( Result::ERROR, __( 'The email could not be sent. Use another method or contact the site administrator.', 'potomac-mfa' ), array( 'reason' => 'wp_mail_failed' ) );
		}

		UserState::set_record(
			$user->ID,
			'email_otp_' . $purpose,
			array(
				'hash'     => self::hash( $code ),
				'to'       => strtolower( $address ),
				'attempts' => 0,
				'expires'  => time() + $ttl,
			)
		);
		return Result::ok_result();
	}

	/**
	 * Check a code for an address and purpose.
	 */
	public function check( int $user_id, string $address, string $code, string $purpose ): Result {
		$name   = 'email_otp_' . $purpose;
		$record = UserState::record( $user_id, $name );
		if ( ! $record || ( $record['to'] ?? '' ) !== strtolower( $address ) ) {
			return new Result( Result::EXPIRED, __( 'The code has expired. Request a new code.', 'potomac-mfa' ) );
		}
		$record['attempts'] = (int) $record['attempts'] + 1;
		if ( hash_equals( (string) $record['hash'], self::hash( preg_replace( '/\D/', '', $code ) ) ) ) {
			UserState::delete_record( $user_id, $name );
			return Result::ok_result();
		}
		if ( $record['attempts'] >= self::MAX_ATTEMPTS ) {
			UserState::delete_record( $user_id, $name );
			return new Result( Result::EXPIRED, __( 'Too many incorrect codes. Request a new code.', 'potomac-mfa' ) );
		}
		UserState::set_record( $user_id, $name, $record );
		return new Result( Result::INVALID, __( 'The code is not valid or has expired.', 'potomac-mfa' ) );
	}

	public function prompt( \WP_User $user ): string {
		return sprintf(
			/* translators: %s: masked email address. */
			__( 'Enter the verification code sent to %s.', 'potomac-mfa' ),
			self::mask( UserState::email( $user->ID ) )
		);
	}

	/**
	 * Masked address, e.g. "r•••@example.com".
	 */
	public static function mask( string $email ): string {
		$parts = explode( '@', $email );
		if ( 2 !== count( $parts ) ) {
			return $email;
		}
		return mb_substr( $parts[0], 0, 1 ) . '•••@' . $parts[1];
	}

	/**
	 * @return string[]
	 */
	public static function headers(): array {
		$headers = array( 'Content-Type: text/plain; charset=UTF-8' );
		$from    = (string) Options::get( 'email.from_address', '' );
		if ( '' !== $from ) {
			$name      = (string) Options::get( 'email.from_name', '' );
			$headers[] = 'From: ' . ( '' !== $name ? sprintf( '"%s" <%s>', str_replace( '"', '', $name ), $from ) : $from );
		}
		return $headers;
	}

	private static function hash( string $code ): string {
		return hash_hmac( 'sha256', $code, wp_salt( 'auth' ) );
	}
}
